 management.get('/businesses/:id/report',async ctx=>{const a=await user(ctx.req.raw),id=identifier(ctx.req.param('id')),m=await access(pool,a,id);if(m.locationId)fail(403,'scope_restricted');const days=Number(ctx.req.query('days')||30);if(![7,30,90].includes(days))fail(400,'invalid_period');const since=new Date(now()-days*86400000);
  const rows=(await pool.query(`SELECT l.id,l.name,l.status,
   (SELECT COALESCE(SUM(v.visits),0)::int FROM venue_page_visits v WHERE v.location_id=l.id AND v.day>=($2::timestamptz AT TIME ZONE l.timezone)::date) AS "pageVisits",
   (SELECT COALESCE(SUM(sc.scans),0)::int FROM venue_qr_scans sc JOIN venue_qr_codes q ON q.id=sc.qr_id WHERE q.location_id=l.id AND sc.day>=($2::timestamptz AT TIME ZONE l.timezone)::date) AS "qrScans",
   (SELECT COUNT(*)::int FROM venue_guest_sessions s WHERE s.location_id=l.id AND s.created_at>=$2) AS sessions,
   (SELECT COALESCE(SUM(f.attempts),0)::int FROM venue_failed_entries f WHERE f.location_id=l.id AND f.day>=($2::timestamptz AT TIME ZONE l.timezone)::date) AS "failedEntries",
   (SELECT COUNT(*)::int FROM venue_game_runs r WHERE r.location_id=l.id AND r.started_at>=$2) AS starts,
   (SELECT COUNT(*)::int FROM venue_game_runs r WHERE r.location_id=l.id AND r.started_at>=$2 AND r.completed_at IS NOT NULL) AS completions
   FROM venue_locations l WHERE l.business_id=$1 ORDER BY lower(l.name)`,[id,since])).rows;
  const games=(await pool.query('SELECT r.game_id AS "gameId",COUNT(*)::int AS starts,COUNT(r.completed_at)::int AS completions FROM venue_game_runs r JOIN venue_locations l ON l.id=r.location_id WHERE l.business_id=$1 AND r.started_at>=$2 GROUP BY r.game_id ORDER BY starts DESC,r.game_id',[id,since])).rows;
  const totals=rows.reduce((t:any,r:any)=>{for(const k of['pageVisits','qrScans','sessions','failedEntries','starts','completions'])t[k]+=r[k];return t},{pageVisits:0,qrScans:0,sessions:0,failedEntries:0,starts:0,completions:0});
  return json({days,totals,locations:rows,games,definitions:'Page visits are page loads, QR scans are successful scans of permanent QR codes, sessions are successful code entries, starts and completions are host-reported game events. These are aggregate counts, not unique people or verified restaurant visits.'})});
 management.get('/locations/:id/report',async ctx=>{const a=await user(ctx.req.raw),l=await location(pool,a,identifier(ctx.req.param('id'))),days=Number(ctx.req.query('days')||30);if(![7,30,90].includes(days))fail(400,'invalid_period');const since=new Date(now()-days*86400000),r=await pool.query('SELECT COUNT(*)::int AS starts,COUNT(completed_at)::int AS completions,game_id AS "gameId" FROM venue_game_runs WHERE location_id=$1 AND started_at>=$2 GROUP BY game_id ORDER BY starts DESC',[l.id,since]);const sessions=await pool.query('SELECT COUNT(*)::int AS n FROM venue_guest_sessions WHERE location_id=$1 AND created_at>=$2',[l.id,since]);const visits=await pool.query('SELECT COALESCE(SUM(visits),0)::int AS n FROM venue_page_visits WHERE location_id=$1 AND day>=($2::timestamptz AT TIME ZONE $3)::date',[l.id,since,l.timezone]);const failed=await pool.query('SELECT COALESCE(SUM(attempts),0)::int AS n FROM venue_failed_entries WHERE location_id=$1 AND day>=($2::timestamptz AT TIME ZONE $3)::date',[l.id,since,l.timezone]);return json({days,pageVisits:visits.rows[0].n,sessions:sessions.rows[0].n,failedEntries:failed.rows[0].n,games:r.rows,definitions:'Page visits are page loads, sessions are successful code entries, starts and completions are host-reported game events. These are not unique people or verified restaurant visits.'})});
