 venues.post('/:slug/entry',async ctx=>{const l=await publicLocation(pool,identifier(ctx.req.param('slug')),now());const existing=await pool.query('SELECT id,expires_at FROM venue_guest_sessions WHERE location_id=$1 AND token_hash=$2 AND revoked_at IS NULL AND expires_at>$3',[l.id,guestHash(ctx.req.raw,l.id,c),new Date(now())]);if(existing.rowCount)return json(await payload(l,existing.rows[0]));const ip=ctx.req.header('x-railway-client-ip')||ctx.req.header('x-forwarded-for')?.split(',').at(-1)||'unknown';const attemptKey='entry:'+l.id+':'+ip;const limited=await pool.query('SELECT 1 FROM venue_rate_limits WHERE key=$1 AND window_at>NOW()-INTERVAL \'15 minutes\' AND attempts>=20',[hash(attemptKey)]);if(limited.rowCount)fail(429,'too_many_attempts');const p=await body(ctx.req.raw),code=typeof p.code==='string'?p.code.toUpperCase().replace(/[\s-]/g,''):'';const row=await currentCode(pool,{...l,rotationAnchor:l.rotation_anchor},c,now());if(!/^(\d{6}|[A-Z2-9]{8})$/.test(code)||!equal(row.verifier,verifier(code,l.id,c.secret))){await rate(pool,attemptKey,20);if(await hit(pool,'locfail:'+l.id,15)===300){await currentCode(pool,{...l,rotationAnchor:l.rotation_anchor},c,now(),true,undefined);await audit(pool,'system','code.auto_replaced',l.business_id,l.id,{reason:'many failed entries'})}await pool.query('INSERT INTO venue_failed_entries(location_id,day,attempts) VALUES ($1,(NOW() AT TIME ZONE $2)::date,1) ON CONFLICT(location_id,day) DO UPDATE SET attempts=venue_failed_entries.attempts+1',[l.id,l.timezone]);fail(400,'invalid_venue_code')}const raw=token(),id=crypto.randomUUID(),expires=new Date(row.expires_at);await pool.query('INSERT INTO venue_guest_sessions(id,location_id,token_hash,code_id,expires_at) VALUES ($1,$2,$3,$4,$5)',[id,l.id,hash(raw),row.id,expires]);const result=json(await payload(l,{expires_at:expires}));result.headers.append('Set-Cookie',`${guestCookie(l.id,c)}=${raw}; Path=/api/venue/${l.slug}; HttpOnly; SameSite=Strict; Max-Age=${Math.max(1,Math.floor((expires.getTime()-now())/1000))}${c.production?'; Secure':''}`);return result});
